def is_power_of_five(k):
    if k <= 0:
        return False
    while k > 1 and k % 5 == 0:
        k //= 5
    return k == 1

values_n = [3, 7, 11, 15, 19]
results = {}
for n in values_n:
    value = (2**n) - 3
    is_power = is_power_of_five(value)
    results[n] = (value, is_power)

print("Results for n=3, 7, 11, 15, 19:")
for n, (value, is_power) in results.items():
    print(f"n={n}: 2^n - 3 = {value}. Is power of 5: {is_power}")

def is_power_of_5(N):
    if N <= 0:
        return False
    while N % 5 == 0:
        N //= 5
    return N == 1

# We only need to test n such that n = 3 (mod 4)
max_n = 25
solutions = []
for n in range(3, max_n + 1):
    if n % 4 == 3:
        # Calculate 2^n - 3
        diff = (2**n) - 3

        if diff <= 0:
            continue

        # Check if diff is a power of 5
        if is_power_of_5(diff):
            k = 0
            temp = diff
            while temp > 1:
                temp //= 5
                k += 1
            solutions.append((n, k))

print("Solutions found (n, k):")
for sol in solutions:
    print(sol)

def power(a, b, m):
    res = 1
    a %= m
    while b > 0:
        if b % 2 == 1:
            res = (res * a) % m
        a = (a * a) % m
        b //= 2
    return res

for n in range(1, 25):
    if power(2, n, 25) == 3:
        print(f"n={n}")

